    pt:{eyebrow:"Produção musical à medida",title:"Crie a sua música original",hero:"Transforme uma ideia, letra ou melodia numa música original criada para a sua voz e estilo — com master pronta para lançar.",introTitle:"Não é uma base genérica. É a sua música.",intro:["Não precisa de uma música acabada nem de experiência. Partimos do que tem, definimos a direção em conjunto e construímos instrumental, arranjo e produção vocal de raiz.","O pacote inclui duas sessões focadas de três horas. A mistura e masterização profissional estão incluídas gratuitamente, com uma master exclusiva pronta para lançamento."],includes:[["Instrumental à medida","Produção original criada de raiz para as suas referências e identidade."],["Desenvolvimento da música","Apoio na estrutura, refrões, arranjo, energia e direção musical."],["Voz principal","Sessão orientada para captar uma interpretação segura."],["Produção vocal completa","Harmonias, coros, ad-libs, camadas, detalhes e efeitos."],["Mistura e master grátis","Incluídas no preço do pacote, sem extras."],["Entrega pronta a lançar","Master final e direitos exclusivos para lançar a música."]],process:[["Sessão um","Criamos instrumental, som, estrutura e arranjo."],["Sessão dois","Gravamos voz principal, harmonias, coros e camadas criativas."],["Produção final","Finalizamos, misturamos, masterizamos e entregamos a música."]],priceTitle:"Pacote completo de música original",prices:[["Pacote de música original","€500"],["Sinal de reserva","€100"],["Saldo","Pago por etapas"]],sideTitle:"Plano de pagamento",side:["€100 de sinal","€150 na primeira sessão","€150 na segunda sessão","€100 na conclusão","IVA incluído"],faq:[["Preciso saber compor?","Não. Traga um conceito, letra, melodia, referência ou apenas o tipo de música que quer."],["Posso lançar a música?","Sim. O pacote inclui direitos exclusivos para lançar a música original."],["A mistura e master são extra?","Não. Estão incluídas gratuitamente no pacote."]],proof:[["6 horas","Duas sessões focadas"],["100% original","Criada para o seu estilo"],["Sinal de €100","Reserve o primeiro horário"]]},
    fr:{eyebrow:"Production musicale sur mesure",title:"Créez votre chanson originale",hero:"Transformez une idée, un texte ou une mélodie en un titre original conçu pour votre voix et votre style — avec un master prêt à sortir.",introTitle:"Pas une instrumentale générique. Votre disque.",intro:["Aucune chanson terminée ni expérience n’est nécessaire. Nous partons de votre idée et construisons l’instrumental, l’arrangement et la production vocale de zéro.","Le forfait comprend deux sessions ciblées de trois heures. Mixage et mastering professionnels sont offerts, avec un master exclusif prêt à sortir."],includes:[["Instrumental sur mesure","Production originale créée selon vos références et votre identité."],["Développement du titre","Structure, accroches, arrangement, énergie et direction musicale."],["Voix principale","Session accompagnée pour obtenir une performance assurée."],["Production vocale complète","Harmonies, chœurs, ad-libs, couches, détails et effets."],["Mix & master offerts","Inclus dans le prix du forfait, sans supplément."],["Livraison prête à sortir","Master final et droits exclusifs pour publier votre titre."]],process:[["Session un","Création de l’instrumental, du son, de la structure et de l’arrangement."],["Session deux","Enregistrement des voix, harmonies, chœurs et couches créatives."],["Production finale","Finalisation, mixage, mastering et livraison."]],priceTitle:"Forfait chanson originale",prices:[["Forfait chanson originale","500 €"],["Acompte de réservation","100 €"],["Solde","Payé par étapes"]],sideTitle:"Échéancier",side:["100 € d’acompte","150 € à la première session","150 € à la deuxième session","100 € à la livraison","TVA comprise"],faq:[["Dois-je savoir composer ?","Non. Apportez un concept, un texte, une mélodie, une référence ou simplement un style."],["Puis-je sortir le titre ?","Oui. Le forfait inclut les droits exclusifs pour sortir la chanson originale."],["Le mixage est-il en supplément ?","Non. Mixage et mastering professionnels sont offerts dans le forfait."]],proof:[["6 heures","Deux sessions ciblées"],["100 % original","Créé pour votre style"],["Acompte 100 €","Réservez le premier créneau"]]}
