    pt:{eyebrow:"Mistura e masterização",title:"Faça cada detalhe funcionar",hero:"Clareza, impacto e emoção para auscultadores, carros, clubes, rádio e streaming, sem perder a identidade da música.",introTitle:"Uma finalização ao serviço da música.",intro:["A mistura transforma gravações separadas numa interpretação coesa. Equilibramos timbre, profundidade, dinâmica e movimento.","A masterização é o controlo de qualidade final: nível, equilíbrio tonal, consistência e ficheiros corretos para lançamento."],includes:[["Revisão","Verificamos ficheiros, organização e preparação técnica."],["Equilíbrio detalhado","Níveis, panorâmica, EQ e compressão segundo o arranjo."],["Profundidade","Reverb, delay, saturação e automação com intenção."],["Foco vocal","Clareza e presença sem perder emoção."],["Testes de reprodução","Decisões que funcionam em sistemas reais."],["Masters finais","Ficheiros de alta qualidade para distribuição e arquivo."]],process:[["Enviar","Forneça stems, mistura provisória e referências."],["Construir","Criamos a mistura com foco em impacto e tradução."],["Aprovar","Revê o resultado, envia notas e recebe as masters."]],priceTitle:"Preços de mistura e masterização",prices:[["Mistura · até 12 canais","€125 IVA incluído"],["Mistura · até 24 canais","€185 IVA incluído"],["Mistura · até 48 canais","€270 IVA incluído"],["Masterização","€75 IVA incluído"],["Mistura + master · até 12 canais","€185 IVA incluído"],["Mistura + master · até 24 canais","€245 IVA incluído"],["Mistura + master · até 48 canais","€335 IVA incluído"]],sideTitle:"Para um orçamento exato",side:["Número e duração das músicas","Quantidade aproximada de stems","Misturas provisórias","Duas ou três referências","Data de lançamento e formatos"],faq:[["Podem misturar à distância?","Sim. Envie os stems e todo o processo pode ser remoto."],["Que ficheiros precisam?","Stems WAV consolidados, sem clipping, mistura provisória e referências."],["As revisões estão incluídas?","O número de revisões é definido no orçamento antes de começar."]],proof:[["Detalhado","Decisões com intenção"],["Consistente","Funciona em vários sistemas"],["Pronto a lançar","Ficheiros profissionais"]]},
    fr:{eyebrow:"Mixage & mastering",title:"Faites entendre chaque détail",hero:"Clarté, impact et émotion pour casques, voitures, clubs, radio et streaming, sans perdre l’identité du morceau.",introTitle:"Une finition au service du titre.",intro:["Le mixage transforme des prises séparées en une performance cohérente. Nous équilibrons couleur, profondeur, dynamique et mouvement.","Le mastering est le contrôle qualité final : niveau, équilibre tonal, cohérence de lecture et fichiers adaptés à la sortie."],includes:[["Vérification","Contrôle des fichiers et de leur préparation technique."],["Équilibre précis","Niveaux, panoramique, EQ et compression selon l’arrangement."],["Profondeur","Réverbération, délai, saturation et automation utiles."],["Voix en avant","Clarté et présence tout en gardant l’émotion."],["Tests d’écoute","Des choix qui fonctionnent sur de vrais systèmes."],["Masters finaux","Fichiers haute qualité pour distribution et archives."]],process:[["Envoyer","Fournissez stems, rough mix et références."],["Façonner","Nous construisons le mix avec impact et cohérence."],["Valider","Vous révisez, commentez et recevez les masters."]],priceTitle:"Tarifs mixage & mastering",prices:[["Mixage · jusqu’à 12 pistes","125 € TVA comprise"],["Mixage · jusqu’à 24 pistes","185 € TVA comprise"],["Mixage · jusqu’à 48 pistes","270 € TVA comprise"],["Mastering","75 € TVA comprise"],["Mix + master · jusqu’à 12 pistes","185 € TVA comprise"],["Mix + master · jusqu’à 24 pistes","245 € TVA comprise"],["Mix + master · jusqu’à 48 pistes","335 € TVA comprise"]],sideTitle:"Pour un devis précis",side:["Nombre et durée des titres","Nombre approximatif de stems","Rough mixes actuels","Deux ou trois références","Date de sortie et formats"],faq:[["Le mixage peut-il être réalisé à distance ?","Oui. Envoyez les stems et tout le suivi peut se faire à distance."],["Quels fichiers faut-il ?","Stems WAV consolidés, sans saturation, plus un rough mix et des références."],["Les révisions sont-elles incluses ?","Le périmètre des révisions est défini dans le devis avant le début."]],proof:[["Précis","Des choix utiles"],["Cohérent","Sur tous les systèmes"],["Prêt à sortir","Fichiers professionnels"]]}
