    pt:{eyebrow:"Voz-off remota",title:"Som broadcast, esteja o cliente onde estiver",hero:"Cabine profissional, técnico experiente e direção remota em direto para publicidade, cinema, conteúdos, jogos e narração.",introTitle:"O espaço, sinal e processo que os profissionais esperam.",intro:["Grave o talento em Loulé enquanto produtores, agências e realizadores acompanham e dirigem a partir de qualquer lugar. O SessionLink Pro permite colaboração em tempo real.","Tratamos da técnica de microfone, captação limpa, talkback e organização dos ficheiros para que todos se concentrem na interpretação."],includes:[["Cabine broadcast","Espaço controlado e cadeia vocal profissional."],["Neumann U87","Microfone de estúdio para uma voz detalhada e natural."],["Direção remota","Escuta e comunicação em direto via SessionLink Pro."],["Técnico experiente","Níveis, posição do microfone e fluxo de sessão."],["Tomadas organizadas","Nomes claros, gestão de takes e notas do cliente."],["Entrega flexível","Ficheiros brutos ou editados e masterizados."]],process:[["Briefing","Envie guião, pronúncias, especificações e participantes."],["Ligação","O talento grava em Loulé e a equipa remota dirige em direto."],["Entrega","Organizamos e entregamos os takes aprovados no formato pedido."]],priceTitle:"Preços de sessões remotas",prices:[["Sessão remota · 1 hora","€175 IVA incluído"],["Meio dia · 10:00–14:00","€600 IVA incluído"],["Dia completo · 10:00–17:00","€1.000 IVA incluído"]],sideTitle:"Trabalhos selecionados",side:["Maybelline New York","Orange","Red Bull Media","Real Madrid","Projetos com Karim Benzema, Nick Fellows e Alison Doody"],faq:[["O realizador pode participar remotamente?","Sim. O SessionLink Pro permite ouvir, comunicar e dirigir em direto."],["Podem seguir especificações de entrega?","Sim. Envie sample rate, bit depth, nomes e requisitos de edição."],["Fornecem locutores?","Fale connosco sobre voz, idioma e apoio de produção necessário."]],proof:[["Direção em direto","SessionLink Pro"],["Qualidade broadcast","Cabine e cadeia profissional"],["Clientes globais","Entrega para agências"]]},
