    en:{eyebrow:"Photography studio",title:"Images with character",hero:"Portraits, artist imagery, family sessions and business content created with direction, professional lighting and a clear purpose.",introTitle:"More than standing in front of a camera.",intro:["A strong photography session starts with knowing how the images will be used. We plan the tone, backgrounds and shot list, then guide you through the session so the results feel natural and intentional.","Choose a focused mini session or build a wider library for a launch, brand, family milestone or ongoing social content."],includes:[["Creative planning","Purpose, visual references, outfits and key shots discussed in advance."],["Professional lighting","Studio lighting shaped for flattering, consistent results."],["Gentle direction","Clear posing and expression guidance, even if you dislike cameras."],["Thoughtful selection","The strongest photographs chosen from the session."],["Professional edits","Colour, contrast, crop and considered retouching."],["Useful delivery","High-resolution images ready for print, web and social use."]],process:[["Plan","Tell us where the images will appear and the look you want."],["Shoot","Work through a focused shot list with lighting and direction."],["Select & edit","We choose, refine and deliver the agreed final collection."]],priceTitle:"Photography packages",prices:[["Mini · 30 min · 5 images","€120"],["Signature · 1 hour · 10 images","€220"],["Premium · 90 min · 20 images","€310"],["Business branding · 1 hour · 15 images","€280"]],sideTitle:"Optional additions",side:["Additional edited images","Complete gallery upgrades","Social reels","Behind-the-scenes video","Additional studio time"],faq:[["What should I wear?","Bring a small selection that fits the intended mood. We can help you narrow it down before the shoot."],["Can families book?","Yes. The studio works well for family portraits and experience packages."],["When will I receive the photographs?","Your expected edit and delivery time is confirmed before the session."]],proof:[["Directed","Relaxed help throughout"],["Professionally edited","Finished, consistent images"],["From €120","VAT included"]]},
    pt:{eyebrow:"Estúdio fotográfico",title:"Imagens com personalidade",hero:"Retratos, imagens de artista, famílias e conteúdos empresariais com direção, iluminação profissional e propósito claro.",introTitle:"Muito mais do que ficar em frente à câmara.",intro:["Uma boa sessão começa por perceber como as imagens serão usadas. Planeamos ambiente, fundos e shot list e orientamos todo o processo.","Escolha uma mini sessão ou crie uma biblioteca maior para lançamento, marca, família ou redes sociais."],includes:[["Planeamento criativo","Objetivo, referências, roupa e imagens essenciais."],["Iluminação profissional","Luz de estúdio consistente e favorecedora."],["Orientação tranquila","Ajuda clara com poses e expressão."],["Seleção cuidada","Escolha das fotografias mais fortes."],["Edição profissional","Cor, contraste, enquadramento e retoque considerado."],["Entrega útil","Alta resolução para impressão, web e redes sociais."]],process:[["Planear","Diga-nos onde vai usar as imagens e o estilo pretendido."],["Fotografar","Seguimos uma lista focada com luz e direção."],["Selecionar e editar","Escolhemos, refinamos e entregamos a coleção."]],priceTitle:"Pacotes de fotografia",prices:[["Mini · 30 min · 5 imagens","€120"],["Signature · 1 hora · 10 imagens","€220"],["Premium · 90 min · 20 imagens","€310"],["Branding · 1 hora · 15 imagens","€280"]],sideTitle:"Extras disponíveis",side:["Imagens editadas adicionais","Galeria completa","Reels sociais","Vídeo de bastidores","Tempo adicional de estúdio"],faq:[["O que devo vestir?","Traga algumas opções adequadas ao ambiente. Ajudamos a escolher antes."],["Aceitam famílias?","Sim. O estúdio funciona muito bem para retratos de família."],["Quando recebo as fotografias?","O prazo de edição e entrega é confirmado antes da sessão."]],proof:[["Com direção","Apoio descontraído"],["Edição profissional","Imagens consistentes"],["Desde €120","IVA incluído"]]},
